import math
def control(obs):
    h=obs['hitch_deg']
    a=math.radians(h)
    cam=obs.get('views',{}).get('camera')
    steer=1.8*h
    if cam:
        pts=[]
        for b,d in cam.get('target_corners',[]):
            b=math.radians(b)
            x=d*math.cos(b); y=d*math.sin(b)
            s=-math.cos(a)*x+math.sin(a)*y
            n=math.sin(a)*x+math.cos(a)*y
            pts.append((s,n))
        center=None
        if len(pts)==4:
            pts.sort()
            near=((pts[0][0]+pts[1][0])/2,(pts[0][1]+pts[1][1])/2)
            far=((pts[2][0]+pts[3][0])/2,(pts[2][1]+pts[3][1])/2)
            if far[0]-near[0]>1:
                center=near[1]+(3.0-near[0])*(far[1]-near[1])/(far[0]-near[0])
        if center is None:
            sides=[[],[]]
            for b,d in cam.get('walls',[]):
                b=math.radians(b)
                x=d*math.cos(b); y=d*math.sin(b)
                s=-math.cos(a)*x+math.sin(a)*y
                n=math.sin(a)*x+math.cos(a)*y
                if 2<s<4.5:
                    sides[0 if n<0 else 1].append((abs(s-3),n))
            if all(sides):
                vals=[]
                for side in sides:
                    side.sort()
                    vals.append(sum(p[1] for p in side[:3])/len(side[:3]))
                center=sum(vals)/2
        if center is not None:
            desired=max(-27,min(27,math.degrees(math.atan2(5.2*center,9))))
            steer=1.8*h-2*desired
    return (max(-34,min(34,steer)),-0.45,-23)

