import math
def control(obs):
    h=obs['hitch_deg']; theta=math.radians(-h)
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam:
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            a=math.radians(b)-theta
            s=-d*math.cos(a); l=d*math.sin(a)
            if 1<s<13 and abs(l)>1.5:
                sides[0 if l>0 else 1].append((s,l))
        fits=[]
        for pts in sides:
            if len(pts)>=2:
                n=len(pts); sx=sum(p[0] for p in pts); sy=sum(p[1] for p in pts)
                den=sum(p[0]**2 for p in pts)-sx*sx/n
                m=(sum(x*y for x,y in pts)-sx*sy/n)/max(.1,den)
                fits.append((sy/n-m*sx/n,m))
        if len(fits)==2:
            look=8.0
            lateral=sum(a+m*look for a,m in fits)/2
            desired=max(-35,min(35,math.degrees(math.atan(20.4*lateral/(look*look)))))
    steer=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))+1.5*(h-desired)
    return (max(-42,min(42,steer)),-0.9,-41)

